#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"

/* Block size used for the optimized x-update (GEMV with A^T).
 * Small enough to stay in L1/L2, large enough to amortize overhead. */
#ifndef GEMVER_X_BLOCK_SIZE
# define GEMVER_X_BLOCK_SIZE 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use local restrict-qualified pointers for better alias analysis.
   - Keep row-major access to A in all kernels.
   - For the x update (x += beta * A^T * y), use a blocked algorithm:
       * Access A row-wise (good spatial locality).
       * Keep a small block of x in a stack buffer to reduce memory traffic.
     The per-element accumulation order with respect to j is preserved,
     so floating-point results for each x[i] match the original code.
*/
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  /* Use the PolyBench-provided loop bound. */
  const int n_ = _PB_N;

  /* Local restrict-qualified views of the arrays.  This tells the
     compiler that these pointers do not alias each other, which
     helps vectorization and other optimizations. */
  DATA_TYPE (*restrict A_)[n] = A;

  const DATA_TYPE *restrict u1_ = u1;
  const DATA_TYPE *restrict u2_ = u2;
  const DATA_TYPE *restrict v1_ = v1;
  const DATA_TYPE *restrict v2_ = v2;

  DATA_TYPE *restrict w_ = w;
  DATA_TYPE *restrict x_ = x;
  const DATA_TYPE *restrict y_ = y;
  const DATA_TYPE *restrict z_ = z;

  /* 1) Rank-1-like update:
       A[i][j] += u1[i] * v1[j] + u2[i] * v2[j];

     We keep row-major traversal of A, and hoist u1[i]/u2[i] out of
     the inner loop to reduce redundant loads. */
  for (i = 0; i < n_; i++)
    {
      DATA_TYPE *restrict Ai = A_[i];
      const DATA_TYPE ui1 = u1_[i];
      const DATA_TYPE ui2 = u2_[i];

#pragma GCC ivdep
      for (j = 0; j < n_; j++)
        Ai[j] += ui1 * v1_[j] + ui2 * v2_[j];
    }

  /* 2) x = x + beta * A^T * y

     Original code:
       for i
         for j
           x[i] += beta * A[j][i] * y[j];

     That accesses A column-wise with a large stride.  Here we rewrite
     it as a blocked algorithm over x so that:

       - A is still accessed row-wise (good spatial locality).
       - Each small block of x is kept in a stack buffer and updated
         for all j, then written back once.

     For each element x[k], the updates are still applied in order of
     j = 0..n_-1, exactly as in the original nest, so the per-element
     floating-point accumulation order is preserved. */
  for (int i0 = 0; i0 < n_; i0 += GEMVER_X_BLOCK_SIZE)
    {
      const int i_end = i0 + GEMVER_X_BLOCK_SIZE < n_
                        ? i0 + GEMVER_X_BLOCK_SIZE
                        : n_;
      const int block_len = i_end - i0;

      /* Small block buffer for x.  Size is constant (stack allocation),
         but we only use the first block_len entries. */
      DATA_TYPE x_block[GEMVER_X_BLOCK_SIZE];

      /* Load current block of x into the buffer. */
      for (int ii = 0; ii < block_len; ++ii)
        x_block[ii] = x_[i0 + ii];

      /* Perform the blocked GEMV with A^T. */
      for (j = 0; j < n_; ++j)
        {
          const DATA_TYPE beta_yj = beta * y_[j];
          const DATA_TYPE *restrict Aj = &A_[j][i0]; /* row j, columns i0..i_end-1 */

#pragma GCC ivdep
          for (int ii = 0; ii < block_len; ++ii)
            x_block[ii] += Aj[ii] * beta_yj;
        }

      /* Store the updated block back to x. */
      for (int ii = 0; ii < block_len; ++ii)
        x_[i0 + ii] = x_block[ii];
    }

  /* 3) x[i] += z[i];  Simple element-wise addition. */
#pragma GCC ivdep
  for (i = 0; i < n_; i++)
    x_[i] += z_[i];

  /* 4) w = w + alpha * A * x

     Original:
       for i
         for j
           w[i] += alpha * A[i][j] * x[j];

     We keep row-major access to A and accumulate into a register
     'wi' to avoid repeated loads/stores of w[i].  This preserves the
     order of accumulation for each w[i] with respect to j. */
  for (i = 0; i < n_; i++)
    {
      const DATA_TYPE *restrict Ai = A_[i];
      DATA_TYPE wi = w_[i];

#pragma GCC ivdep
      for (j = 0; j < n_; j++)
        wi += alpha * Ai[j] * x_[j];

      w_[i] = wi;
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemver (n, alpha, beta,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(u1),
		 POLYBENCH_ARRAY(v1),
		 POLYBENCH_ARRAY(u2),
		 POLYBENCH_ARRAY(v2),
		 POLYBENCH_ARRAY(w),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y),
		 POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
