      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;

      /* Cache the row pointer to reduce address arithmetic in the inner loop. */
      DATA_TYPE *Ai = A[i];
      for (j = 0; j < n; j++)
        Ai[j] = (DATA_TYPE)((i * j) % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  /* 1) Rank-2 update:
   *      A[i][j] += u1[i]*v1[j] + u2[i]*v2[j]
   *    Optimize by:
   *      - Hoisting u1[i] and u2[i] out of the inner loop.
   *      - Caching the current row pointer A[i] to improve address generation.
   */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE ui1 = u1[i];
      DATA_TYPE ui2 = u2[i];
      DATA_TYPE *Ai = A[i];

      for (j = 0; j < _PB_N; j++)
        Ai[j] = Ai[j] + ui1 * v1[j] + ui2 * v2[j];
    }

  /* 2) x[i] += beta * A[j][i] * y[j]
   *
   * Original version:
   *   for (i)
   *     for (j)
   *       x[i] += beta * A[j][i] * y[j];
   *
   * This accesses A by columns (A[j][i]) with j varying fastest, which gives
   * poor spatial locality on a row-major layout.
   *
   * We interchange the loops to traverse A row-wise:
   *
   *   for (j)
   *     for (i)
   *       x[i] += beta * A[j][i] * y[j];
   *
   * For each fixed i, the sequence of (j) values is still 0.._PB_N-1 in
   * increasing order, so the accumulation order for x[i] is unchanged,
   * preserving numerical behavior while improving cache locality.
   */
  for (j = 0; j < _PB_N; j++)
    {
      DATA_TYPE yj = y[j];
      DATA_TYPE *Aj = A[j]; /* Row j of A */

      for (i = 0; i < _PB_N; i++)
        x[i] = x[i] + beta * Aj[i] * yj;
    }

  /* 3) x[i] += z[i] : simple elementwise vector addition. */
  for (i = 0; i < _PB_N; i++)
    x[i] = x[i] + z[i];

  /* 4) w[i] += alpha * A[i][j] * x[j]
   *
   * Access A row-wise (A[i][j] with j varying fastest) which already matches
   * the memory layout. We additionally:
   *   - Cache the row pointer A[i] in Ai.
   *   - Accumulate into a local scalar 'wi' to reduce repeated loads/stores.
   * This does not change the accumulation order over j for each w[i].
   */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *Ai = A[i];
      DATA_TYPE wi = w[i];

      for (j = 0; j < _PB_N; j++)
        wi = wi + alpha * Ai[j] * x[j];

      w[i] = wi;
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemver (n, alpha, beta,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(u1),
		 POLYBENCH_ARRAY(v1),
		 POLYBENCH_ARRAY(u2),
		 POLYBENCH_ARRAY(v2),
		 POLYBENCH_ARRAY(w),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y),
		 POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

