#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;
  /* Precompute 1/n once and reuse it to replace divisions by
   * multiplications in the initialization. This reduces the number
   * of expensive division operations while preserving the intended
   * mathematical behavior up to normal floating‑point roundoff.
   */
  const DATA_TYPE inv_fn = 1.0 / fn;

  for (i = 0; i < n; i++)
    {
      /* Common factor (i+1)/n used several times below. */
      const DATA_TYPE ratio = ((DATA_TYPE)(i + 1)) * inv_fn;

      u1[i] = (DATA_TYPE)i;
      u2[i] = ratio * 0.5;    /* ((i+1)/fn)/2.0  */
      v1[i] = ratio * 0.25;   /* ((i+1)/fn)/4.0  */
      v2[i] = ratio / 6.0;    /* ((i+1)/fn)/6.0  */
      y[i]  = ratio * 0.125;  /* ((i+1)/fn)/8.0  */
      z[i]  = ratio / 9.0;    /* ((i+1)/fn)/9.0  */

      x[i] = 0.0;
      w[i] = 0.0;

      /* Initialize matrix A row-wise for good spatial locality. */
      for (j = 0; j < n; j++)
        {
          int ij_mod_n = (i * j) % n;
          A[i][j] = ((DATA_TYPE)ij_mod_n) * inv_fn; /* (i*j % n) / n */
        }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  /* Incorporate z into x up front.
   *
   * Original code:
   *   x[i] = 0;
   *   x[i] += sum_j beta * A[j][i] * y[j];
   *   x[i] += z[i];
   *
   * New code:
   *   x[i] = z[i] + sum_j beta * A[j][i] * y[j];
   *
   * which is algebraically equivalent (reordered additions only).
   */
  for (i = 0; i < _PB_N; i++)
    x[i] += z[i];

  /* Fused update of A and computation of x.
   *
   * Original:
   *   for (i)
   *     for (j)
   *       A[i][j] += u1[i]*v1[j] + u2[i]*v2[j];
   *
   *   for (i)
   *     for (j)
   *       x[i] += beta * A[j][i] * y[j];
   *
   * We instead iterate over rows j of A and, for each row:
   *   1) Perform the rank-2 update on A[j][*].
   *   2) Accumulate this updated row's contribution to x.
   *
   * This uses A row-wise (contiguous in memory) for both operations,
   * greatly improving cache locality and reducing the number of full
   * passes over A from two to one.
