  for (j = 0; j < _PB_N; j++)
    {
      DATA_TYPE *Arow = A[j];
      const DATA_TYPE u1j = u1[j];
      const DATA_TYPE u2j = u2[j];
      const DATA_TYPE beta_yj = beta * y[j];

      for (i = 0; i < _PB_N; i++)
        {
          const DATA_TYPE v1i = v1[i];
          const DATA_TYPE v2i = v2[i];

          /* Updated element:
           *   A'[j][i] = A[j][i] + u1[j]*v1[i] + u2[j]*v2[i]
           */
          DATA_TYPE A_ji = Arow[i] + u1j * v1i + u2j * v2i;
          Arow[i] = A_ji;

          /* Contribution of row j to x[i]:
           *   x[i] += beta * A'[j][i] * y[j]
           * (x already contains z[i] from the first loop).
           */
          x[i] += beta_yj * A_ji;
        }
    }

  /* Final matrix-vector product: w = w + alpha * A * x.
   *
   * w is initialized to 0 in init_array(), so this computes:
   *   w[i] = alpha * sum_j A[i][j] * x[j]
   *
   * The inner loop is organized as a row-wise dot product to
   * maximize locality for A and x and to keep the accumulator
   * in a register.
   */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *Ai = A[i];
      DATA_TYPE wi = w[i];

      for (j = 0; j < _PB_N; j++)
        wi += alpha * Ai[j] * x[j];

      w[i] = wi;
    }

#pragma endscop
}


