    {
      const DATA_TYPE *restrict Ai = A_[i];
      DATA_TYPE sum = w_[i];

      for (j = 0; j < _PB_N; j++)
        {
          sum += alpha * Ai[j] * x_[j];
        }

      w_[i] = sum;
    }

#pragma endscop
